234	        if (option.hasAttr("disabled")) return true;
235	        for (Element parent = option.parent(); parent != null && !parent.nameIs("select"); parent = parent.parent()) {
236	            if (parent.nameIs("optgroup") && parent.hasAttr("disabled"))
237	                return true;
238	        }
239	        return false;
240	    }
