                belongs = descendants.contains(el) || linked.contains(el); // implicit: descendant, or linked at parse time
            if (belongs) controls.add(el);
        }
        return controls;
    }

    @Override
    protected void removeChild(Node out) {
        super.removeChild(out);
        linkedEls.remove(out);
    }

    /**
